    if x['patient'] in living:
        if x['patient'] not in latest or x['time']>latest[x['patient']][0]: latest[x['patient']]=(x['time'],x['ecg'])
si=json.load(open('saved_i.json'))['interpretations']
print('saved interps',len(si))
got={x['ecg'] for x in si}
exp={v[1] for v in latest.values()}
