c=collections.Counter(x['reason'] for x in it); print(c)
# nulls check
for x in si:
    if x['rhythm'] in ('AF','ATRIAL_FLUTTER') and x['pr_ms'] is not None: print('PR set for',x['ecg'])
print('living without ECG:',len(living)-len(latest))
"

